window.docContents[137].resolve({"/Onboarding___-Human-Context-Protocols/L5-___-The-oscillation-dies-out/#A-Property-Kind-Calculus-for-Metrology___-proving-quantity-and-unit-laws-in-Lean___-from-ISO___IEC-80000-to-measurement-uncertainty--Onboarding___-Human-Context-Protocols--L5-___-The-oscillation-dies-out--Pull":{"contents":"The oscillator loses energy as its motion fades. This optional rung adds a damper to the nominally named whole-system model. Do not confuse the damper's viscous constant γ with the whole oscillator's decay rate δ. One name is one system: records under that name are its states at different times, configurations, or rival estimates; comparing them is the point. Distinct names are distinct systems.\n\n","context":"A Property Kind Calculus for Metrology: proving quantity and unit laws in Lean, from ISO/IEC 80000 to measurement uncertainty\u0009Onboarding: Human Context Protocols\u0009L5 — The oscillation dies out","header":"5.6.3. Pull","id":"/Onboarding___-Human-Context-Protocols/L5-___-The-oscillation-dies-out/#A-Property-Kind-Calculus-for-Metrology___-proving-quantity-and-unit-laws-in-Lean___-from-ISO___IEC-80000-to-measurement-uncertainty--Onboarding___-Human-Context-Protocols--L5-___-The-oscillation-dies-out--Pull"}});